/* Level overlay code after unclassified; generated by `decomp overlays stubs`, stubs replaced by C as functions are matched. */
#include "types.h"
#include "asm.h"

#define NOT_SDA

#define MACRO_ADDR

/* Ported from rac1-decomp (src/overlays/shared/fastfunc_001FEF78.c: func_L00_002004C0), where it is exact; names translated to the US level program. */

extern float fast_add_rotations(float, float) __asm__("FUN_001fa580");
extern float fast_subtract_rotations(float, float) __asm__("FUN_001fa5c8");
float AbsoluteFloat(float input) __asm__("func_001F99C0");

/* Steps rotation a toward b by at most c, clamped to the remaining difference. */
float FUN_L00_00200510(float a, float b, float c) {
    float r = fast_subtract_rotations(b, a);
    if (!(r > 0.0f)) {
        c = -c;
    }
    if (c > AbsoluteFloat(r)) {
        c = AbsoluteFloat(r);
    } else if (c < -AbsoluteFloat(r)) {
        c = -AbsoluteFloat(r);
    }
    return fast_add_rotations(a, c);
}
